{
  "requirement_id": "SFMC-REQ-035",
  "raw_text": "The pilot shall always be able to override automatic spacecraft controls.",
  "software_requirement_status": "YES",
  "quality_status": "NEEDS_REVIEW",
  "quality_issues": [
    {
      "issue_code": "UNDEFINED_TERM",
      "severity": "MAJOR",
      "explanation": "The requirement uses the term \"automatic spacecraft controls\" without defining what specific controls or systems are included. The SRS does not provide a clear definition or scope for \"automatic spacecraft controls,\" which leads to ambiguity in implementation and verification.",
      "srs_evidence": [
        {
          "locator": "SFMC-REQ-035",
          "excerpt": "The pilot shall always be able to override automatic spacecraft controls."
        },
        {
          "locator": "1.3 Operational Modes",
          "excerpt": "The spacecraft supports the following operating modes:\n1. Standby — spacecraft is powered but not performing a mission.\n2. Manual Flight — the pilot directly controls spacecraft movement.\n3. Autopilot — the SFMC controls the spacecraft toward a pilot-selected destination.\n4. Combat — targeting and defensive functions are enabled.\n5. Emergency — the SFMC prioritizes crew survival and spacecraft recovery."
        }
      ],
      "nasa_references": [
        {
          "document": "NASA-HDBK-2203-5.09",
          "authority": "HANDBOOK_GUIDANCE",
          "section": "§3.1.2",
          "swe_id": null,
          "url": "https://swehb.nasa.gov/spaces/SWEHBVD/pages/102695669/5.09+-+SRS+-+Software+Requirements+Specification"
        }
      ],
      "recommendation": "Define \"automatic spacecraft controls\" explicitly within the SRS or link to a glossary or system definition section. Clarify which subsystems or functions are considered automatic controls and under what conditions the pilot override applies. This will improve clarity and verifiability.",
      "requires_stakeholder_input": true
    },
    {
      "issue_code": "MISSING_QUALIFICATION_PROVISIONS",
      "severity": "MAJOR",
      "explanation": "The requirement does not specify how the pilot override capability will be verified or validated. There are no acceptance criteria or qualification provisions stated to ensure the requirement is testable.",
      "srs_evidence": [
        {
          "locator": "SFMC-REQ-035",
          "excerpt": "The pilot shall always be able to override automatic spacecraft controls."
        }
      ],
      "nasa_references": [
        {
          "document": "NASA-HDBK-2203-5.09",
          "authority": "HANDBOOK_GUIDANCE",
          "section": "§1.c",
          "swe_id": null,
          "url": "https://swehb.nasa.gov/spaces/SWEHBVD/pages/102695669/5.09+-+SRS+-+Software+Requirements+Specification"
        }
      ],
      "recommendation": "Add qualification provisions specifying how the pilot override functionality will be demonstrated, tested, or analyzed to verify compliance with this requirement.",
      "requires_stakeholder_input": false
    }
  ],
  "primary_swe_id": null,
  "primary_swe_strength": null,
  "swe_links": [],
  "summary": "The requirement SFMC-REQ-035 mandates that the pilot must always be able to override automatic spacecraft controls. It is a valid software requirement related to pilot interaction and control. However, the term \"automatic spacecraft controls\" is not defined in the SRS, causing ambiguity. Additionally, the requirement lacks qualification provisions for verification and validation. These issues should be addressed to improve clarity and testability."
}
